fn lookup(table: *const std.StaticStringMap(Entry), abbrev_upper: []const u8, size: Size) ?[]const u8 {
    const entry = table.get(abbrev_upper) orelse return null;
    return switch (size) {
        .xs => entry.xs,
        .sm => entry.sm,
        .md => entry.md,
    };
}

