    "wnba",
};

pub fn tableFor(league_slug: []const u8) ?*const std.StaticStringMap(Entry) {
    if (std.ascii.eqlIgnoreCase(league_slug, "bundesliga")) return &bundesliga;
    if (std.ascii.eqlIgnoreCase(league_slug, "epl")) return &epl;
    if (std.ascii.eqlIgnoreCase(league_slug, "laliga")) return &laliga;
    if (std.ascii.eqlIgnoreCase(league_slug, "ligue1")) return &ligue1;
    if (std.ascii.eqlIgnoreCase(league_slug, "mlb")) return &mlb;
    if (std.ascii.eqlIgnoreCase(league_slug, "mls")) return &mls;
    if (std.ascii.eqlIgnoreCase(league_slug, "nba")) return &nba;
    if (std.ascii.eqlIgnoreCase(league_slug, "ncaaf")) return &ncaaf;
    if (std.ascii.eqlIgnoreCase(league_slug, "ncaam")) return &ncaam;
    if (std.ascii.eqlIgnoreCase(league_slug, "ncaaw")) return &ncaaw;
    if (std.ascii.eqlIgnoreCase(league_slug, "nfl")) return &nfl;
    if (std.ascii.eqlIgnoreCase(league_slug, "nhl")) return &nhl;
    if (std.ascii.eqlIgnoreCase(league_slug, "seriea")) return &seriea;
    if (std.ascii.eqlIgnoreCase(league_slug, "ucl")) return &ucl;
    if (std.ascii.eqlIgnoreCase(league_slug, "wnba")) return &wnba;
    return null;
}

/// abbrev_upper must already be uppercased by the caller.
pub fn teamArt(league_slug: []const u8, abbrev_upper: []const u8, size: Size) ?[]const u8 {
    if (std.ascii.eqlIgnoreCase(league_slug, "bundesliga")) return lookup(&bundesliga, abbrev_upper, size);
    if (std.ascii.eqlIgnoreCase(league_slug, "epl")) return lookup(&epl, abbrev_upper, size);
    if (std.ascii.eqlIgnoreCase(league_slug, "laliga")) return lookup(&laliga, abbrev_upper, size);
    if (std.ascii.eqlIgnoreCase(league_slug, "ligue1")) return lookup(&ligue1, abbrev_upper, size);
    if (std.ascii.eqlIgnoreCase(league_slug, "mlb")) return lookup(&mlb, abbrev_upper, size);
    if (std.ascii.eqlIgnoreCase(league_slug, "mls")) return lookup(&mls, abbrev_upper, size);
    if (std.ascii.eqlIgnoreCase(league_slug, "nba")) return lookup(&nba, abbrev_upper, size);
    if (std.ascii.eqlIgnoreCase(league_slug, "ncaaf")) return lookup(&ncaaf, abbrev_upper, size);
    if (std.ascii.eqlIgnoreCase(league_slug, "ncaam")) return lookup(&ncaam, abbrev_upper, size);
    if (std.ascii.eqlIgnoreCase(league_slug, "ncaaw")) return lookup(&ncaaw, abbrev_upper, size);
    if (std.ascii.eqlIgnoreCase(league_slug, "nfl")) return lookup(&nfl, abbrev_upper, size);
    if (std.ascii.eqlIgnoreCase(league_slug, "nhl")) return lookup(&nhl, abbrev_upper, size);
    if (std.ascii.eqlIgnoreCase(league_slug, "seriea")) return lookup(&seriea, abbrev_upper, size);
    if (std.ascii.eqlIgnoreCase(league_slug, "ucl")) return lookup(&ucl, abbrev_upper, size);
    if (std.ascii.eqlIgnoreCase(league_slug, "wnba")) return lookup(&wnba, abbrev_upper, size);
    return null;
}
